for(const [name,portal] of [['index.html',false],['deckel.html',true]]){
 const file=path.join(root,name),source=fs.readFileSync(file,'utf8'),html=guide(portal);let result;
 if(source.includes('<!-- help-guide:start -->'))result=source.replace(/<!-- help-guide:start -->[\s\S]*?<!-- help-guide:end -->/,html);
 else if(!portal){const from=source.indexOf('<article class="panel help-document">'),end=source.indexOf('\n',from),lineEnd=source.lastIndexOf('</section>',end);if(from<0||lineEnd<from)throw Error('Hilfe nicht gefunden');result=source.slice(0,from)+html+source.slice(lineEnd);}
 else {const from=source.indexOf('<section class="portal-help"><h3>Häufige Fragen</h3>'),end=source.indexOf('<p id="stack-note"',from);if(from<0||end<0)throw Error('Portalhilfe nicht gefunden');result=source.slice(0,from)+html+source.slice(end);}
 if(process.argv.includes('--check')){if(source!==result){console.error(name+': Bildanleitung bitte neu erzeugen.');bad=true;}}else fs.writeFileSync(file,result);
}
if(bad)process.exitCode=1;
